construction.css:
.platform-loan-header{display:flex;justify-content:space-between;align-items:flex-start;padding-top:1.11111111cqi;margin-bottom:1.66666667cqi;}
.platform-loan-heading{display:flex;flex-direction:column;row-gap:0.27777778cqi;}
.platform-loan-inline{display:flex;align-items:center;column-gap:0.55555556cqi;}
.platform-loan-title{font-size:1.38888889cqi;line-height:2.08333333cqi;font-weight:600;color:#121212;}
.platform-loan-record-name{color:#121212;font-weight:500;}
.platform-loan-currency{display:flex;align-items:center;column-gap:0.41666667cqi;padding-top:0.06944444cqi;padding-bottom:0.06944444cqi;padding-left:0.27777778cqi;padding-right:0.69444444cqi;border-top:0.06944444cqi solid #e7e7e7;border-bottom:0.06944444cqi solid #e7e7e7;border-left:0.06944444cqi solid #e7e7e7;border-right:0.06944444cqi solid #e7e7e7;font-size:0.90277778cqi;line-height:1.25000000cqi;font-weight:500;}
.platform-loan-flag{width:1.11111111cqi;height:0.76388889cqi;display:flex;align-items:center;}
.platform-loan-body{display:grid;grid-template-columns:minmax(0,792fr) minmax(0,320fr);column-gap:2.22222222cqi;}
.platform-loan-main{display:flex;flex-direction:column;row-gap:2.22222222cqi;min-width:0;}
.platform-loan-summary{display:flex;flex-direction:column;row-gap:1.66666667cqi;}
.platform-loan-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));column-gap:1.11111111cqi;}
.platform-loan-metric-label{font-size:0.90277778cqi;line-height:1.25000000cqi;font-weight:500;}
.platform-loan-metric-value{font-size:1.25000000cqi;line-height:1.94444444cqi;font-weight:500;color:#121212;margin-top:0.27777778cqi;}
.platform-loan-due-fields{display:flex;flex-direction:column;row-gap:0.27777778cqi;margin-top:0.69444444cqi;}
.platform-loan-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:1.11111111cqi;}
.platform-loan-field-column{display:flex;flex-direction:column;row-gap:0.55555556cqi;}
.platform-loan-field{display:flex;align-items:center;column-gap:0.55555556cqi;white-space:nowrap;}
.platform-loan-details-link{color:#121212;font-weight:500;}
.platform-loan-section-heading{display:flex;justify-content:space-between;align-items:center;min-height:2.22222222cqi;}
.platform-loan-section-title{font-size:1.11111111cqi;line-height:1.66666667cqi;font-weight:600;color:#121212;}
.platform-loan-balances-section{display:flex;flex-direction:column;row-gap:1.11111111cqi;}
.platform-radius-8.platform-loan-balances{overflow:hidden;border-top:0.06944444cqi solid #e7e7e7;border-bottom:0.06944444cqi solid #e7e7e7;border-left:0.06944444cqi solid #e7e7e7;border-right:0.06944444cqi solid #e7e7e7;}
.platform-loan-balance-row{display:grid;grid-template-columns:208fr 194.6667fr 194.6667fr 194.6667fr;min-height:2.77777778cqi;}
.platform-loan-balance-row.is-header{min-height:2.50000000cqi;background-color:#f9f9f9;}
.platform-table-header-cell.platform-loan-balance-heading{border-bottom-color:#e7e7e7;color:#4b4b4b;line-height:1.11111111cqi;}
.platform-table-header-cell.platform-loan-balance-heading.is-numeric{justify-content:flex-end;}
.platform-table-cell.platform-loan-balance-cell{border-bottom-color:#e7e7e7;color:#3d3d3d;font-weight:500;}
.platform-table-cell.platform-loan-balance-cell.is-numeric{justify-content:flex-end;color:#5d5d5d;font-weight:400;}
.platform-loan-aside{display:flex;flex-direction:column;row-gap:1.66666667cqi;min-width:0;}
.platform-loan-blocks{position:relative;height:25.00000000cqi;overflow:hidden;display:flex;flex-direction:column;row-gap:1.11111111cqi;}
.platform-radius-8.platform-loan-plus{display:flex;align-items:center;justify-content:center;width:2.22222222cqi;height:2.22222222cqi;border-top:0.06944444cqi solid #d1d1d1;border-bottom:0.06944444cqi solid #d1d1d1;border-left:0.06944444cqi solid #d1d1d1;border-right:0.06944444cqi solid #d1d1d1;padding:0.55555556cqi;background-color:#fff;box-shadow:0 0.06944444cqi 0.13888889cqi #1018280d;}
.platform-loan-block{display:flex;align-items:flex-start;column-gap:0.55555556cqi;padding-right:1.11111111cqi;}
.platform-loan-block-copy{display:flex;flex-direction:column;row-gap:0.27777778cqi;flex:1;min-width:0;}
.platform-loan-timestamp{font-size:0.90277778cqi;line-height:1.25000000cqi;}
.platform-loan-dots{width:2.22222222cqi;height:2.22222222cqi;padding:0.55555556cqi;display:flex;flex-shrink:0;}
.platform-loan-block-fade{position:absolute;bottom:0;left:0;width:100%;height:6.66666667cqi;background-image:linear-gradient(180deg,rgba(255,255,255,0),#fff);pointer-events:none;}
.platform-loan-customers{display:flex;flex-direction:column;row-gap:1.11111111cqi;}
.platform-loan-customer{display:flex;flex-direction:column;row-gap:0.27777778cqi;}
.platform-loan-customer-link{color:#121212;font-weight:500;text-decoration:underline;}
